function StoreLayout() {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', margin: 0, padding: 0, backgroundColor: '#f8f9fc' }}>
      {/* UPDATED STYLE OVERRIDE: Centering rules for pages and containers */}
      <style>{`
        .about-page, .contact-page, .cart-page, .orders-page, .home-page, .products-page {
          width: 100% !important;
          max-width: 1200px !important; /* Limits width so content doesn't stretch too far */
          margin-left: auto !important;  /* Centers horizontally */
          margin-right: auto !important; /* Centers horizontally */
          box-sizing: border-box !important; 
        }
        body, html {
          margin: 0 !important;
          padding: 0 !important;
          overflow-x: hidden !important;
        }
      `}</style>

      {/* Sidebar Navigation */}
      <div style={{ 
        width: isSidebarOpen ? '250px' : '0px', 
        minWidth: isSidebarOpen ? '250px' : '0px', 
        height: '100vh', 
        position: 'sticky', 
        top: '0', 
        zIndex: 1000,
        overflow: 'hidden',
        transition: 'width 0.3s ease, min-width 0.3s ease'
      }}>
        <Navbar />
      </div>

      {/* Right Side Content + Footer Area */}
      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: '100vh', width: isSidebarOpen ? 'calc(100% - 250px)' : '100%' }}>

        <Hero onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} />

        {/* Updated Main Tag: Centers its child pages and adds padding */}
        <main style={{ flex: 1, padding: '40px 20px', boxSizing: 'border-box', width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <Routes>
            <Route path='/' element={<Home />} />
            <Route path='/products' element={<Products />} />
            <Route path='/about' element={<About />} />
            <Route path='/contact' element={<Contact />} />
            <Route path='/login' element={<LoginSignup />} />
            <Route path='/cart' element={<Cart />} />
            <Route path='/orders' element={<Orders />} />
          </Routes>
        </main>

        <Footer />
      </div>
    </div>
  );
}
